import React from 'react';
import './CategoryShowcase.css';

// ඔයාගේ Assets folder එකේ තියෙන ගැලපෙන පින්තූර මෙතනට දාන්න
import menCategoryImg from '../Assets/men_category.png'; 
import womenCategoryImg from '../Assets/women_category.png';
import accessCategoryImg from '../Assets/accessories_category.png';

const CategoryShowcase = () => {
  return (
    <div className="category-showcase-container">
      <div className="showcase-header">
        <span>INSPIRATION</span>
        <h2>Shop By Category</h2>
        <p>Explore our curated collections tailored just for your lifestyle.</p>
      </div>

      <div className="category-grid">
        {/* 1. Women's Card */}
        <div className="category-card large-card">
          <img src={womenCategoryImg} alt="Women's Collection" />
          <div className="category-overlay">
            <div className="category-info">
              <h3>Women's Collection</h3>
              <p>Elegant & Casual Trends</p>
              <button className="shop-now-btn">Discover More</button>
            </div>
          </div>
        </div>

        {/* Right column for Men and Accessories */}
        <div className="right-column-grid">
          {/* 2. Men's Card */}
          <div className="category-card item-card">
            <img src={menCategoryImg} alt="Men's Collection" />
            <div className="category-overlay">
              <div className="category-info">
                <h3>Men's Wear</h3>
                <p>Smart & Modern Classics</p>
                <button className="shop-now-btn">Shop Now</button>
              </div>
            </div>
          </div>

          {/* 3. Accessories Card */}
          <div className="category-card item-card">
            <img src={accessCategoryImg} alt="Accessories" />
            <div className="category-overlay">
              <div className="category-info">
                <h3>Trending Accessories</h3>
                <p>Complete Your Look</p>
                <button className="shop-now-btn">Explore</button>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default CategoryShowcase;
